def semver_sort(versions):
    def parse_version(version):
        # Split on '+' to remove build metadata
        version = version.split('+')[0]

        # Split on '-' to separate core version and pre-release
        if '-' in version:
            core, prerelease = version.split('-', 1)
            prerelease_identifiers = prerelease.split('.')
        else:
            core = version
            prerelease_identifiers = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        return (major, minor, patch, prerelease_identifiers)

    def prerelease_sort_key(identifiers):
        if identifiers is None:
            # No pre-release sorts after pre-release
            return (1,)

        # Pre-release sorts before no pre-release
        key = [0]
        for identifier in identifiers:
            if identifier.isdigit():
                # All-digit identifiers sort numerically and before non-digit
                key.append((0, int(identifier)))
            else:
                # Non-digit identifiers sort by ASCII and after digit
                key.append((1, identifier))
        return tuple(key)

    # Create list of (sort_key, original_index, version_string)
    indexed_versions = []
    for i, version in enumerate(versions):
        parsed = parse_version(version)
        major, minor, patch, prerelease_identifiers = parsed
        sort_key = (major, minor, patch, prerelease_sort_key(prerelease_identifiers))
        indexed_versions.append((sort_key, i, version))

    # Sort by sort_key, then by original index to maintain stable order
    indexed_versions.sort(key=lambda x: (x[0], x[1]))

    # Extract the sorted version strings
    return [version for _, _, version in indexed_versions]

